SELECT "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.year" AS "year", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.month" AS "month", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.billing_period" AS "billing_period", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.usage_date" AS "usage_date", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.payer_account_id" AS "payer_account_id", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.linked_account_id" AS "linked_account_id", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.purchase_option" AS "purchase_option", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.amortized_cost" AS "amortized_cost", "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.usage_quantity" AS "usage_quantity", "t0"."d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.account_id" AS "account_id", "t0"."d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.parent_account_id" AS "parent_account_id", "t0"."d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.account_name" AS "account_name", "t0"."d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.account_email_id" AS "account_email_id", "t1"."e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.account_id" AS "account_id[organization_map]", "t1"."e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.account_name" AS "account_name[organization_map]", "t1"."e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.ou" AS "ou", "t1"."e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.ou_id" AS "ou_id", "t1"."e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.payer_org_account_id" AS "payer_org_account_id", "t1"."e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.management_account_id" AS "management_account_id"
FROM (
SELECT "year" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.year", "month" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.month", "billing_period" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.billing_period", "usage_date" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.usage_date", "payer_account_id" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.payer_account_id", "linked_account_id" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.linked_account_id", "purchase_option" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.purchase_option", "amortized_cost" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.amortized_cost", "usage_quantity" AS "8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.usage_quantity"
FROM "cid_cur"."ec2_running_cost"
) AS "t"
LEFT JOIN (
SELECT "account_id" AS "d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.account_id", "parent_account_id" AS "d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.parent_account_id", "account_name" AS "d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.account_name", "account_email_id" AS "d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.account_email_id"
FROM "cid_cur"."account_map"
) AS "t0" ON "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.payer_account_id" = "t0"."d1a3a9a4-0569-457f-bd14-9bd53ea96eb8.account_id"
LEFT JOIN (
SELECT "account_id" AS "e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.account_id", "account_name" AS "e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.account_name", "ou" AS "e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.ou", "ou_id" AS "e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.ou_id", "payer_org_account_id" AS "e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.payer_org_account_id", "management_account_id" AS "e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.management_account_id"
FROM "AwsDataCatalog"."optimization_data"."organization_map"
) AS "t1" ON "t"."8f4dd082-917c-4e44-9b7c-57bc6bb33ebe.linked_account_id" = "t1"."e039c9d6-bbdb-40a6-a1e7-89da995f4cb6.account_id"

/* cppi::be1505a1c79017763734e5f3a55572bf1867c04e8bb1181f3115f6bbda70bbbc */
